-- Migration 047: Update tool classification categories with improved LLM classifications
-- Per implementation plan: Tool Seed Data feature
-- Generated by: npx ts-node scripts/classify-builtin-tools.ts (with improved prompt)
--
-- Key improvements from migration 039:
-- - Added dataChanges to email/message send operations (they create sent records)
-- - lever_send_offer now includes customerCommunication (offers go to candidates)
-- - lever_schedule_interview now includes hiringDecisions (advances candidate)
-- - slack_schedule_message now includes externalPublishing (will publish)
-- - jira_add_comment now includes externalPublishing (visible to team)

-- Gmail: send operations create data (sent items)
UPDATE tool_classification_cache SET categories = ARRAY['customerCommunication', 'dataChanges'] WHERE tool_name = 'gmail_send_email';
UPDATE tool_classification_cache SET categories = ARRAY['customerCommunication', 'dataChanges'] WHERE tool_name = 'gmail_reply_email';
UPDATE tool_classification_cache SET categories = ARRAY['customerCommunication', 'dataChanges'] WHERE tool_name = 'gmail_forward_email';

-- Stripe: financial operations also create data records
UPDATE tool_classification_cache SET categories = ARRAY['financialActions', 'dataChanges'] WHERE tool_name = 'stripe_create_invoice';
UPDATE tool_classification_cache SET categories = ARRAY['financialActions', 'dataChanges'] WHERE tool_name = 'stripe_refund_charge';
UPDATE tool_classification_cache SET categories = ARRAY['financialActions', 'dataChanges'] WHERE tool_name = 'stripe_create_charge';
UPDATE tool_classification_cache SET categories = ARRAY['financialActions', 'dataChanges'] WHERE tool_name = 'stripe_create_subscription';
UPDATE tool_classification_cache SET categories = ARRAY['financialActions', 'dataChanges'] WHERE tool_name = 'stripe_cancel_subscription';

-- HubSpot: send email creates data
UPDATE tool_classification_cache SET categories = ARRAY['customerCommunication', 'dataChanges'] WHERE tool_name = 'hubspot_send_email';

-- Slack: messages are both data creation and external publishing
UPDATE tool_classification_cache SET categories = ARRAY['dataChanges', 'externalPublishing'] WHERE tool_name = 'slack_send_message';
UPDATE tool_classification_cache SET categories = ARRAY['dataChanges', 'externalPublishing'] WHERE tool_name = 'slack_schedule_message';
UPDATE tool_classification_cache SET categories = ARRAY['dataChanges', 'externalPublishing'] WHERE tool_name = 'slack_send_dm';
UPDATE tool_classification_cache SET categories = ARRAY['dataChanges', 'externalPublishing'] WHERE tool_name = 'slack_upload_file';

-- Lever: hiring actions now properly include hiringDecisions
UPDATE tool_classification_cache SET categories = ARRAY['dataChanges', 'hiringDecisions'] WHERE tool_name = 'lever_update_candidate_status';
UPDATE tool_classification_cache SET categories = ARRAY['customerCommunication', 'hiringDecisions', 'dataChanges'] WHERE tool_name = 'lever_send_offer';
UPDATE tool_classification_cache SET categories = ARRAY['dataChanges', 'hiringDecisions'] WHERE tool_name = 'lever_reject_application';
UPDATE tool_classification_cache SET categories = ARRAY['dataChanges', 'hiringDecisions'] WHERE tool_name = 'lever_schedule_interview';

-- Zendesk: reply creates data and communicates with customer
UPDATE tool_classification_cache SET categories = ARRAY['customerCommunication', 'dataChanges'] WHERE tool_name = 'zendesk_reply_ticket';

-- Jira: comments are visible to project team (external publishing)
UPDATE tool_classification_cache SET categories = ARRAY['dataChanges', 'externalPublishing'] WHERE tool_name = 'jira_add_comment';

-- Verify no NULL categories exist
DO $$
DECLARE
  null_count INT;
BEGIN
  SELECT COUNT(*) INTO null_count FROM tool_classification_cache WHERE categories IS NULL;
  IF null_count > 0 THEN
    RAISE EXCEPTION 'Found % tools with NULL categories', null_count;
  END IF;
END $$;
